-- Horizon Wear: restaura 12 cadastros e acrescenta 20 produtos.
-- Fotografias revisadas em supabase/catalog/horizon-20260927.json.
-- Mantém IDs, pedidos, preços existentes e todas as quantidades já registradas.
-- Novos tamanhos começam com estoque zero até confirmação do estoque físico.
begin;
create temporary table hw_catalog_before on commit drop as
 select id,preco,preco_promocional from public.products;
create temporary table hw_stock_before on commit drop as
 select id,estoque from public.product_sizes;
create temporary table hw_catalog_seed on commit drop as
 select * from jsonb_to_recordset($catalog$[{"slug": "camiseta-slim-fit-preta", "nome": "Camiseta Preta Selo Circular", "categoria": "camisetas", "preco": 129.9, "imagem": "black-tee", "descricao": "Camiseta preta de manga curta, gola redonda e pequeno selo circular no peito.", "origem": "existente"}, {"slug": "camiseta-estampada-rock", "nome": "Camiseta Preta Estampa Rock", "categoria": "camisetas", "preco": 139.9, "imagem": "rock-tee", "descricao": "Camiseta preta com estampa branca de mão em estilo rock na parte frontal.", "origem": "restaurado"}, {"slug": "calca-alfaiataria-bege", "nome": "Calça Chino Bege", "categoria": "calcas", "preco": 189.9, "imagem": "beige-pants", "descricao": "Calça bege de corte afunilado, com bolsos laterais e visual casual.", "origem": "existente"}, {"slug": "calca-jogger-preta", "nome": "Calça Jogger Preta", "categoria": "calcas", "preco": 159.9, "imagem": "jogger", "descricao": "Calça jogger preta, com modelagem afunilada e punhos nas barras.", "origem": "restaurado"}, {"slug": "moletom-canguru-cinza", "nome": "Moletom com Capuz Cinza", "categoria": "moletons", "preco": 219.9, "imagem": "grey-hoodie", "descricao": "Moletom cinza mescla com capuz, mangas longas e punhos ajustados.", "origem": "restaurado"}, {"slug": "blusa-estampada-premium", "nome": "Moletom Preto Estampa Tomorrow", "categoria": "moletons", "preco": 149.9, "imagem": "printed-sweat", "descricao": "Moletom preto com capuz e estampa branca e verde com a frase I'll See You Tomorrow.", "origem": "restaurado"}, {"slug": "tenis-urban-preto-marrom", "nome": "Tênis Casual Caramelo e Preto", "categoria": "calcados", "preco": 279.9, "imagem": "caramel-shoes", "descricao": "Tênis caramelo com detalhes pretos, cadarços no mesmo tom e solado branco.", "origem": "existente"}, {"slug": "sapato-social-couro", "nome": "Sapato Social Marrom de Fivela", "categoria": "calcados", "preco": 249.9, "imagem": "formal-shoes", "descricao": "Sapato social marrom com fechamento lateral por fivela e acabamento liso.", "origem": "restaurado"}, {"slug": "relogio-atemporal-couro-edition", "nome": "Relógio Clássico Pulseira Marrom", "categoria": "relogios", "preco": 349.9, "imagem": "leather-watch", "descricao": "Relógio de mostrador claro, caixa metálica e pulseira marrom com textura marcada.", "origem": "existente"}, {"slug": "relogio-classic-bronze", "nome": "Relógio Metálico Mostrador Grafite", "categoria": "relogios", "preco": 299.9, "imagem": "metal-watch", "descricao": "Relógio de pulseira metálica, caixa redonda e mostrador grafite.", "origem": "restaurado"}, {"slug": "bone-aba-curva", "nome": "Boné Aba Curva Cinza", "categoria": "acessorios", "preco": 89.9, "imagem": "grey-cap", "descricao": "Boné cinza com aba curva, costuras aparentes e visual sem estampa frontal.", "origem": "existente"}, {"slug": "chapeu-bucket-preto", "nome": "Chapéu Bucket Preto", "categoria": "acessorios", "preco": 79.9, "imagem": "bucket", "descricao": "Chapéu bucket preto de aba curta, com costuras circulares e etiqueta frontal.", "origem": "restaurado"}, {"slug": "corrente-prateada", "nome": "Corrente Prateada Clássica", "categoria": "acessorios", "preco": 99.9, "imagem": "necklace", "descricao": "Corrente de elos em tom prateado, sem pingente, para usar junto à gola.", "origem": "restaurado"}, {"slug": "perfume-bleu-de-chanel", "nome": "Perfume Bleu de Chanel", "categoria": "acessorios", "preco": 159.9, "imagem": "perfume", "descricao": "Frasco azul-escuro Bleu de Chanel com tampa preta. Consulte volume e concentração com a loja antes da compra.", "origem": "restaurado"}, {"slug": "jaqueta-couro-preta", "nome": "Jaqueta Preta com Zíper", "categoria": "jaquetas", "preco": 349.9, "imagem": "black-jacket", "descricao": "Jaqueta preta de acabamento liso, com zíper frontal e detalhes metálicos.", "origem": "existente"}, {"slug": "camisa-social-branca", "nome": "Camisa Social Branca", "categoria": "camisas", "preco": 179.9, "imagem": "white-shirt", "descricao": "Camisa branca de mangas longas, gola tradicional e fechamento frontal por botões.", "origem": "restaurado"}, {"slug": "oculos-de-sol", "nome": "Óculos de Sol Armação Preta", "categoria": "acessorios", "preco": 149.9, "imagem": "sunglasses", "descricao": "Óculos de armação preta, lentes escuras e formato retangular arredondado.", "origem": "restaurado"}, {"slug": "tenis-casual-branco", "nome": "Tênis Branco com Faixa Vermelha", "categoria": "calcados", "preco": 289.9, "imagem": "white-shoes", "descricao": "Tênis branco de cano baixo, cadarços brancos e faixa lateral vermelha e azul.", "origem": "restaurado"}, {"slug": "camiseta-essencial-branca", "nome": "Camiseta Essencial Branca", "categoria": "camisetas", "preco": 99.9, "imagem": "white-tee", "descricao": "Camiseta branca lisa, com gola redonda e mangas curtas. Uma base simples para o dia a dia.", "origem": "novo"}, {"slug": "camiseta-verde-bordado", "nome": "Camiseta Verde com Bordado", "categoria": "camisetas", "preco": 119.9, "imagem": "green-tee", "descricao": "Camiseta verde de gola redonda, com pequeno bordado colorido no peito.", "origem": "novo"}, {"slug": "camiseta-rosa-estampa-central", "nome": "Camiseta Rosa Estampa Central", "categoria": "camisetas", "preco": 119.9, "imagem": "pink-tee", "descricao": "Camiseta rosa com pequena estampa escura central, mangas curtas e gola redonda.", "origem": "novo"}, {"slug": "camiseta-preta-lettering", "nome": "Camiseta Preta Lettering", "categoria": "camisetas", "preco": 129.9, "imagem": "black-print-tee", "descricao": "Camiseta preta com lettering branco discreto na frente e gola redonda.", "origem": "novo"}, {"slug": "camiseta-branca-estampa-hotel", "nome": "Camiseta Branca Estampa Hotel", "categoria": "camisetas", "preco": 109.9, "imagem": "white-print-tee", "descricao": "Camiseta branca de manga curta com pequena estampa Hotel em preto.", "origem": "novo"}, {"slug": "moletom-gola-redonda-branco", "nome": "Moletom Gola Redonda Branco", "categoria": "moletons", "preco": 189.9, "imagem": "ivory-sweat", "descricao": "Moletom branco sem capuz, de gola redonda, mangas longas e punhos canelados.", "origem": "novo"}, {"slug": "moletom-preto-minimal", "nome": "Moletom Preto Minimal", "categoria": "moletons", "preco": 199.9, "imagem": "black-sweat", "descricao": "Moletom preto sem capuz, com gola redonda e detalhe discreto no peito.", "origem": "novo"}, {"slug": "moletom-marrom-cafe", "nome": "Moletom Marrom Café", "categoria": "moletons", "preco": 199.9, "imagem": "brown-sweat", "descricao": "Moletom marrom café de gola redonda, mangas longas e acabamento canelado.", "origem": "novo"}, {"slug": "moletom-azul-marinho-selo", "nome": "Moletom Azul-Marinho com Selo", "categoria": "moletons", "preco": 209.9, "imagem": "blue-sweater", "descricao": "Moletom azul-marinho sem capuz, com pequeno selo amarelo no peito.", "origem": "novo"}, {"slug": "jeans-azul-escuro-reto", "nome": "Calça Jeans Azul-Escuro Reta", "categoria": "calcas", "preco": 219.9, "imagem": "light-jeans", "descricao": "Calça jeans azul-escuro de pernas retas, sem rasgos e com bolsos frontais.", "origem": "novo"}, {"slug": "jeans-preto-classico", "nome": "Calça Jeans Preta Clássica", "categoria": "calcas", "preco": 219.9, "imagem": "black-jeans", "descricao": "Calça jeans preta com costuras escuras, bolsos e barra dobrada na apresentação.", "origem": "novo"}, {"slug": "jeans-azul-claro", "nome": "Calça Jeans Azul-Claro", "categoria": "calcas", "preco": 209.9, "imagem": "blue-jeans", "descricao": "Calça jeans de lavagem azul-clara, com bolsos frontais e fechamento por botão.", "origem": "novo"}, {"slug": "mochila-urbana-azul-marinho", "nome": "Mochila Urbana Azul-Marinho", "categoria": "acessorios", "preco": 189.9, "imagem": "black-backpack", "descricao": "Mochila azul-marinho com bolso frontal de zíper, alça superior e pequeno detalhe amarelo.", "origem": "novo"}, {"slug": "mochila-vinho", "nome": "Mochila Vinho com Bolso Frontal", "categoria": "acessorios", "preco": 229.9, "imagem": "red-backpack", "descricao": "Mochila vinho com acabamento texturizado, bolso frontal e alça superior.", "origem": "novo"}, {"slug": "mochila-marrom-conhaque", "nome": "Mochila Marrom Conhaque", "categoria": "acessorios", "preco": 239.9, "imagem": "brown-backpack", "descricao": "Mochila marrom conhaque com acabamento texturizado e bolso frontal com zíper.", "origem": "novo"}, {"slug": "mochila-azul-fivelas", "nome": "Mochila Azul com Fivelas", "categoria": "acessorios", "preco": 259.9, "imagem": "blue-backpack", "descricao": "Mochila azul-escura com aba superior, duas fivelas frontais e bolsos laterais.", "origem": "novo"}, {"slug": "tenis-esportivo-vermelho", "nome": "Tênis Esportivo Vermelho e Branco", "categoria": "calcados", "preco": 299.9, "imagem": "red-shoes", "descricao": "Tênis vermelho com cadarços no mesmo tom, detalhe lateral branco e solado branco.", "origem": "novo"}, {"slug": "kit-relogios-pulseira-branca", "nome": "Kit 2 Relógios de Pulseira Branca", "categoria": "relogios", "preco": 359.9, "imagem": "white-watch", "descricao": "Conjunto visual com dois relógios de pulseira branca: um de mostrador claro e outro de mostrador preto. Consulte as especificações com a loja.", "origem": "novo"}, {"slug": "bone-branco-liso", "nome": "Boné Branco Liso", "categoria": "acessorios", "preco": 89.9, "imagem": "white-cap", "descricao": "Boné inteiramente branco, sem estampa, com aba curva e costuras discretas.", "origem": "novo"}, {"slug": "bone-vermelho-bordado", "nome": "Boné Vermelho com Bordado", "categoria": "acessorios", "preco": 99.9, "imagem": "red-cap", "descricao": "Boné vermelho com bordado claro na frente e aba curva.", "origem": "novo"}]$catalog$::jsonb)
 as p(slug text,nome text,categoria text,preco numeric,imagem text,descricao text,origem text);
insert into public.categories(nome,slug,grupo,imagem_url,ordem) values
 ('Camisetas','camisetas','roupas','/img/catalog/white-tee.jpg',1),
 ('Calças','calcas','roupas','/img/catalog/beige-pants.jpg',2),
 ('Moletons','moletons','roupas','/img/catalog/grey-hoodie.jpg',3),
 ('Camisas','camisas','roupas','/img/catalog/white-shirt.jpg',4),
 ('Jaquetas','jaquetas','roupas','/img/catalog/black-jacket.jpg',5),
 ('Calçados','calcados','calcados','/img/catalog/caramel-shoes.jpg',6),
 ('Relógios','relogios','relogios','/img/catalog/leather-watch.jpg',7),
 ('Acessórios','acessorios','acessorios','/img/catalog/grey-cap.jpg',8)
 on conflict(slug) do update set imagem_url=excluded.imagem_url,ordem=excluded.ordem;
insert into public.products(categoria_id,nome,slug,descricao,preco,ativo,destaque,lancamento)
 select c.id,s.nome,s.slug,s.descricao,s.preco,true,
 s.imagem in ('white-tee','pink-tee','green-tee','caramel-shoes','black-tee','blue-backpack','grey-hoodie','red-shoes'),
 s.origem='novo'
 from hw_catalog_seed s join public.categories c on c.slug=s.categoria
 on conflict(slug) do update set nome=excluded.nome,descricao=excluded.descricao,
 categoria_id=excluded.categoria_id,ativo=true,destaque=excluded.destaque,lancamento=excluded.lancamento;
update public.product_images i set url='/img/catalog/'||s.imagem||'.jpg'
 from public.products p join hw_catalog_seed s on s.slug=p.slug
 where i.product_id=p.id and i.ordem=0;
insert into public.product_images(product_id,url,ordem)
 select p.id,'/img/catalog/'||s.imagem||'.jpg',0
 from public.products p join hw_catalog_seed s on s.slug=p.slug
 where not exists(select 1 from public.product_images i where i.product_id=p.id and i.ordem=0);
insert into public.product_sizes(product_id,tamanho,estoque)
 select p.id,t.tamanho,0 from public.products p join hw_catalog_seed s on s.slug=p.slug
 cross join lateral unnest(case
 when s.categoria='calcados' then array['39','40','41','42','43']
 when s.categoria='calcas' then array['38','40','42','44']
 when s.categoria in ('camisetas','moletons','camisas','jaquetas') then array['P','M','G','GG']
 else array['Único'] end) as t(tamanho)
 where not exists(select 1 from public.product_sizes ps where ps.product_id=p.id and ps.tamanho=t.tamanho);
do $$ begin
 if exists(select 1 from hw_stock_before b left join public.product_sizes s on s.id=b.id
 where s.id is null or s.estoque is distinct from b.estoque) then
 raise exception 'Estoque existente alterado: abortando'; end if;
 if exists(select 1 from hw_catalog_before b left join public.products p on p.id=b.id
 where p.id is null or p.preco is distinct from b.preco or p.preco_promocional is distinct from b.preco_promocional) then
 raise exception 'Preço existente alterado: abortando'; end if;
 if (select count(*) from hw_catalog_seed s join public.products p on p.slug=s.slug where p.ativo)<>38 then
 raise exception 'Catálogo incompleto: abortando'; end if;
end $$;
select count(*) as produtos_revisados,
 count(*) filter(where s.origem='novo') as novos,
 count(*) filter(where s.origem='restaurado') as restaurados
 from hw_catalog_seed s join public.products p on p.slug=s.slug;
commit;
